import{_ as l,b as s,c as t,g as a}from"./chunks/framework.86O3EbG5.js";const b=JSON.parse('{"title":"单词怪兽 PRD","description":"","frontmatter":{},"headers":[],"relativePath":"public/word-zombie/prd.md","filePath":"public/word-zombie/prd.md"}'),e={name:"public/word-zombie/prd.md"};function d(p,i,n,h,o,r){return s(),t("div",null,[...i[0]||(i[0]=[a(`<h1 id="单词怪兽-prd" tabindex="-1">单词怪兽 PRD</h1><p>给实现用的设计说明。单局 3–8 分钟，面向小学英语认词和默写。核心循环是「看见词 → 打出英文 → 豌豆点名击杀」。奖励只强化打对，不给免费击杀。角色沿用涂鸦木屋、原创豌豆和单词怪兽，不使用马里奥或植物大战僵尸的官方形象、贴图、音效。</p><p>失败要短、能立刻再试。除「木屋被攻破」外，必须有通关结算。</p><p>关卡不按「认词关 / 默写关」拆成两关。同一局里，每个单词出现两次：第一次认词，第二次默写。两种牌子可以同时在场。</p><h2 id="产品与受众" tabindex="-1">产品与受众</h2><ul><li>孩子：打字保卫木屋，在一局里把词表每个词先认一遍、再默写一遍。</li><li>家长：在大厅录入词表，调节每批数量和基础移动速度。</li><li>场景：博客静态页小游戏，无账号、无联网对战。</li></ul><h2 id="核心循环" tabindex="-1">核心循环</h2><ol><li>单词怪兽从右侧持牌子靠近木屋。</li><li>玩家对场上可见怪兽的英文做前缀匹配；拼完则对该只发射豌豆。</li><li>打对：击杀、朗读英文；该次出现从牌堆消耗。</li><li>打错：清空缓冲，豌豆短暂僵直，不扣木屋血。</li><li>怪兽贴上植株：扣木屋 HP；该次出现不算过，按原模式回到牌堆末尾。</li></ol><p>同一份家长词表打一关。不要做成无限复用词表的无尽波，也不要切到另一关才开始默写。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  lobby[大厅词表] --&gt; play[一关混出]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  play --&gt; first[该词第一次认词]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  play --&gt; second[该词第二次默写]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  first --&gt;|打对| second</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  play --&gt;|每词两次都打对且HP大于0| win[通关结算]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  play --&gt;|HP归零| lose[失败再试]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  win --&gt; streak[连胜加速再来]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">  lose --&gt; lobby</span></span></code></pre></div><h2 id="通关条件" tabindex="-1">通关条件</h2><p>本关 / 本局通关：木屋 HP &gt; 0，且词表里每个词都成功击杀两次（先认词，后默写）。</p><p>验收：</p><ul><li>词表当作一副牌。每个词有两次必须打对的出现：第 1 次认词，第 2 次默写。</li><li>某词只有打对认词之后，才允许再刷出它的默写。</li><li>场上同时存在的怪兽数量不超过大厅「每批单词怪兽」。认词怪和默写怪可混在同一批里。</li><li>怪兽漏到植株只扣血；该次出现按<strong>当前模式</strong>回到牌堆末尾（认词漏了仍是认词，默写漏了仍是默写），不能算该次已过。</li><li>牌没打完时，不得把未到次数的词循环复用成额外新怪（禁止当前 <code>pickWord</code> 在用尽后回到全词表抽取）。</li><li>两次出现都打完、场上无活怪、HP &gt; 0，进入通关结算。</li></ul><h2 id="关卡" tabindex="-1">关卡</h2><p>只有一关，不设认词关、默写关，不设关间过场。</p><h3 id="同一词的两次出现" tabindex="-1">同一词的两次出现</h3><p><strong>第一次：认词</strong></p><ul><li>牌子：英文在上、中文在下（与现有一致）。</li><li>输入：打出英文。</li><li>速度：家长滑条 × 连胜系数。</li></ul><p><strong>第二次：默写</strong></p><ul><li>牌子：只显示中文，不显示英文。</li><li>输入：仍打英文。匹配规则不变（对英文做前缀匹配）。</li><li>速度：该只怪兽在认词有效速度上再乘约 0.85（回忆比再认难）。</li><li>出场：仅当该词的认词已被打对。</li></ul><p>验收：</p><ul><li>HUD、标题、过场都不得把本局标成「第 1 关认词 / 第 2 关默写」。</li><li>默写牌子不得出现英文；打对后仍朗读英文。</li><li>词表 3 个词则本关需打对 6 次；进度分母为 <code>词表数 × 2</code>。</li></ul><h3 id="出牌顺序" tabindex="-1">出牌顺序</h3><p>建议实现：认词牌先洗入待发堆；某词认词被击杀后，把它的默写牌追加到队尾（或插入偏后位置），让孩子先见词、隔一会儿再默写，而不是立刻同一词连刷两次。场上仍受每批上限约束。</p><h2 id="失败与再试" tabindex="-1">失败与再试</h2><p>木屋 HP 到 0 即失败。</p><ul><li>保留现有失败 overlay。</li><li>文案须带本关进度，例如「还剩 6 次没打对」（含未完成的认词和默写）。</li><li>提供立刻再试（用原词重来本关）和回大厅改词。</li><li>失败清连胜。</li></ul><h2 id="更多可玩性设计" tabindex="-1">更多可玩性设计</h2><h3 id="连击与临时加成" tabindex="-1">连击与临时加成</h3><p>连续打对累计连击（认词、默写都算）。打错或漏怪（贴上植株）清零。</p><table tabindex="0"><thead><tr><th>连击</th><th>效果</th></tr></thead><tbody><tr><td>3</td><td>豌豆发亮</td></tr><tr><td>5</td><td>怪兽脚底「墨水粘住」约 3 秒（全体减速），可刷新</td></tr><tr><td>8</td><td>木屋少量回血，HP 不超过上限</td></tr></tbody></table><p>验收：连击加成不得直接击杀或清场。</p><h3 id="图鉴收集" tabindex="-1">图鉴收集</h3><p>击败过的怪兽种类写入本地。图鉴卡片标记「见过 / 击败过」。不新增抽卡、商店、解锁墙。</p><h3 id="连胜加难" tabindex="-1">连胜加难</h3><p>本关通关：连胜 +1。下一局有效速度 = 家长速度滑条 × <code>1.08 ^ 连胜</code>，上限约 1.5× 家长值。失败清零。每批数量仍只由家长输入框决定。</p><h3 id="汤姆大叔口播" tabindex="-1">汤姆大叔口播</h3><p>用 <code>speechSynthesis</code> 中文短句，与击杀时的英文朗读错开、不叠读。</p><ul><li>开局：怪兽拿着单词牌冲过来了，帮我看着木屋。</li><li>场上出现本局第一只默写怪：有的牌子只剩中文了，英文要你自己想。</li><li>5 连击：写得真准，墨水把它们的脚粘住了。</li><li>通关：木屋保住了。</li><li>失败：木屋要重修了，我们再试一次。</li></ul><h2 id="进度与结算" tabindex="-1">进度与结算</h2><p>HUD 增加：<code>已打对 / (词表总数 × 2)</code>、连击。可用小标记区分本次是认词还是默写（例如默写牌角标「默」），但不要做成两关名称。保留木屋 HP 与拼写缓冲。</p><p>通关 overlay（需新增，现仅有失败界面）按本关结束时评 1–3 星，只作反馈，不锁关：</p><ul><li>1 星：本关通关</li><li>2 星：结束时 HP &gt; 50%</li><li>3 星：本关无漏怪（没有怪兽贴上植株）</li></ul><h2 id="界面与-hud" tabindex="-1">界面与 HUD</h2><ul><li>大厅：词表、每批数量、基础速度、图鉴入口、开始。开始进入本关。</li><li>局内：进度（已打对 / 总次数）、连击、HP、拼写、僵直提示。</li><li>暂停：继续、编辑词表、图鉴、重新开始（重开本关）。</li><li>胜利：星级、击杀数、连胜、再来一局、回大厅。</li><li>失败：进度、再试、改词。</li><li>不要关间过场，不要「进入默写关」按钮。</li></ul><h2 id="非目标" tabindex="-1">非目标</h2><ul><li>每日签到、体力、商店、账号、排行榜</li><li>免费清怪、炸弹、自动完成单词</li><li>把认词和默写硬拆成两关或两张地图</li><li>无尽模式、多世界地图</li><li>第三方游戏 IP 的形象、贴图、音效</li></ul><h2 id="实现备注" tabindex="-1">实现备注</h2><p>本文件先定设计，实现时再改代码。要点：</p><ul><li>将随机复用词表改为本关牌堆：每词最多两次出现，先认后默；漏怪按当前模式回队尾。</li><li>新增胜利 overlay；HUD 进度分母为词数 × 2。</li><li><code>drawWordCard</code> 按该只怪兽的模式画：认词英+中，默写只中文。</li><li>连击状态（发光、减速、回血）写在 <code>game.js</code>，不新增道具栏。</li><li>图鉴击败记录、连胜记录用 <code>localStorage</code>（可与现有 <code>oasis-word-zombie-*</code> 并列新键）。</li><li>口播与 <code>speakWord</code> 排队，避免中英文同时播。</li></ul>`,51)])])}const g=l(e,[["render",d]]);export{b as __pageData,g as default};
